:root {
  --color-bg: #fff8f0;
  --color-border: #c0392b;
  --color-title: #922b21;
  --color-season: #e67e22;
  --color-text: #5d3a1a;
  --color-muted: #a04000;
  --color-divider: #e59866;
  --color-badge-bg: #fdebd0;
  --color-badge-border: #e67e22;
}

.jar-label {
  background-color: var(--color-bg);
  border: 3px solid var(--color-border);
  border-radius: 12px;
  width: 220px;
  padding: 18px 20px 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  outline: 2px dashed var(--color-divider);
  outline-offset: -8px;
}

.label-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.label-season {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--color-season);
}

.label-title {
  font-size: 26px;
  font-weight: 800;
  color: var(--color-title);
  margin: 0;
  line-height: 1.1;
  text-align: center;
}

.label-divider {
  width: 80%;
  height: 2px;
  background-color: var(--color-divider);
  border-radius: 2px;
}

.label-body {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: 100%;
}

.label-weight {
  font-size: 11px;
  font-weight: 600;
  color: var(--color-muted);
  letter-spacing: 1px;
  margin: 0;
  text-transform: uppercase;
}

.label-details {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
  width: 100%;
}

.detail-item {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  color: var(--color-text);
}

.detail-key {
  font-weight: 600;
  color: var(--color-muted);
}

.detail-val {
  font-weight: 700;
  color: var(--color-title);
}

.label-footer {
  margin-top: 2px;
}

.label-badge {
  background-color: var(--color-badge-bg);
  border: 1.5px solid var(--color-badge-border);
  border-radius: 20px;
  padding: 3px 12px;
  font-size: 12px;
  font-weight: 700;
  color: var(--color-season);
  letter-spacing: 0.5px;
}
